const $=s=>document.querySelector(s);const num=v=>Number(v||0);const safeParse=(v,f={})=>{try{return JSON.parse(v)||f}catch{return f}};
function readLocal(){const keys=Object.keys(localStorage);let answered=0,correct=0,xp=0,active=[];for(const k of keys){const low=k.toLowerCase();if(!/(progress|module|quiz|learning|xp)/.test(low))continue;const d=safeParse(localStorage.getItem(k),null);if(!d||typeof d!=="object")continue;answered+=num(d.answered||d.questionsAnswered||d.totalAnswered);correct+=num(d.correct||d.correctAnswers);xp+=num(d.xp||d.aclXp||d.points);const title=d.moduleTitle||d.title||d.module;if(title&&num(d.answered||d.questionsAnswered)>0)active.push({title,done:num(d.answered||d.questionsAnswered),total:num(d.total||d.questionCount||350)});}return{answered,correct,xp,active:[...new Map(active.map(x=>[x.title,x])).values()].slice(0,2)}}
function setText(id,v){const e=$(id);if(e)e.textContent=v}
function pct(a,b){return b?Math.round(a/b*100):0}
async function profile(){try{const sb=window.supabase;if(!sb?.createClient)return null;const cfg=window.ACL_CONFIG||window.SUPABASE_CONFIG||{};if(!cfg.url||!(cfg.anonKey||cfg.key))return null;const c=sb.createClient(cfg.url,cfg.anonKey||cfg.key);const {data:{user}}=await c.auth.getUser();if(!user)return null;return user}catch{return null}}
function renderContinue(items){const host=$('#continueList');if(!items.length)return;host.innerHTML=items.map(m=>`<div class="continue-item"><b>${m.title}</b><span>${m.done} / ${m.total} · ${pct(m.done,m.total)}%</span><a href="modules.html">Continue</a></div>`).join('')}
function renderFriends(){const stored=safeParse(localStorage.getItem('acl_friends'),[]);if(!Array.isArray(stored)||!stored.length)return;$('#friendsList').innerHTML=stored.slice(0,4).map((f,i)=>`<div class="friend"><i>${i+1}</i><b>${f.name||'Friend'}</b><small>${num(f.xp).toLocaleString()} XP</small></div>`).join('');$('#activityList').innerHTML=stored.slice(0,4).map(f=>`<div class="activity"><b>${f.name||'Friend'}</b> is progressing through ACL <span>Recently</span></div>`).join('')}
async function init(){const local=readLocal();const user=await profile();const meta=user?.user_metadata||{};const name=meta.display_name||meta.full_name||meta.name||localStorage.getItem('display_name')||'Doctor';setText('#welcomeName',name);setText('#avatar',(name.match(/\b\w/g)||['A','C']).slice(0,2).join('').toUpperCase());const answered=local.answered;const accuracy=answered?Math.round(local.correct/answered*100):0;const xp=local.xp||num(localStorage.getItem('acl_xp'));const mastery=num(localStorage.getItem('acl_mastery'))||accuracy;setText('#topXp',xp.toLocaleString());setText('#progressXp',xp.toLocaleString());setText('#questionsAnswered',answered.toLocaleString());setText('#accuracyValue',accuracy+'%');setText('#masteryValue',mastery+'%');$('#masteryRing').style.background=`conic-gradient(var(--blue) ${mastery}%,#e9e8fb 0)`;setText('#modulesActive',local.active.length||0);setText('#modulesCompleted',local.active.filter(m=>m.done>=m.total).length);renderContinue(local.active);renderFriends();const goal=num(localStorage.getItem('acl_weekly_goal'))||100;const weekly=num(localStorage.getItem('acl_weekly_questions'));const gp=Math.min(100,pct(weekly,goal));setText('#goalTarget',goal);setText('#goalDone',weekly);setText('#goalPercent',gp+'%');$('#goalPercent').parentElement.style.background=`conic-gradient(var(--mint) ${gp}%,#edf2f6 0)`;setText('#weeklyXp','+'+num(localStorage.getItem('acl_weekly_xp')).toLocaleString()+' XP');setText('#streakDays',num(localStorage.getItem('acl_streak'))||'—');$('#editGoal').onclick=()=>{const v=prompt('Weekly question goal',String(goal));if(v&&num(v)>0){localStorage.setItem('acl_weekly_goal',String(num(v)));location.reload()}};$('#introPlay').onclick=()=>alert('Add your ACL introduction video URL and this card will play it here.');}
init();